begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select has_function('public','get_crm_insights_v1',array['jsonb'],'CRM analytics endpoint exists');
select ok(not has_function_privilege('anon','get_crm_insights_v1(jsonb)','EXECUTE'),'anonymous denied');
insert into public.branches(id,name) values ('20261009-0000-4000-8000-000000000001','Synthetic insights branch');
insert into auth.users(id,email) values ('20261009-0000-4000-8000-000000000002','insights@example.invalid');
insert into public.users(id,name,email,role,branch_id,active) values ('20261009-0000-4000-8000-000000000002','SYNTHETIC INSIGHTS','insights@example.invalid','salesperson','20261009-0000-4000-8000-000000000001',true);
insert into public.crm_sso_access_grants(jewelos_user_id,legacy_crm_user_id,crm_auth_user_id,work_email,active) values ('20261009-0000-4000-8000-000000000002','20261009-0000-4000-8000-000000000002','20261009-0000-4000-8000-000000000002','insights@example.invalid',true);
insert into clients(client_id,primary_name) values ('20261009-0000-4000-8000-000000000003','Synthetic client');
insert into client_timeline(client_id,event_date,event_type,buy_status,branch_id,salesperson_id) values
 ('20261009-0000-4000-8000-000000000003',now(),'READY_PRODUCT_PURCHASE','YES','20261009-0000-4000-8000-000000000001','20261009-0000-4000-8000-000000000002'),
 ('20261009-0000-4000-8000-000000000003',now(),'NON_PURCHASE_VISIT','NO','20261009-0000-4000-8000-000000000001','20261009-0000-4000-8000-000000000002');
insert into visit_forms(client_timeline_id,not_bought_reasons) select id,array['Synthetic price','Synthetic selection'] from client_timeline where client_id='20261009-0000-4000-8000-000000000003' and buy_status='NO';
insert into not_bought_followups(id,client_id,branch_id,entered_by,status,next_followup_date) values ('20261009-0000-4000-8000-000000000004','20261009-0000-4000-8000-000000000003','20261009-0000-4000-8000-000000000001','20261009-0000-4000-8000-000000000002','PENDING',(now() at time zone 'Asia/Kolkata')::date-8);
update not_bought_followups set status='ALREADY PURCHASED FROM MK JEWELS',call_response='CONNECTED' where id='20261009-0000-4000-8000-000000000004';
set local role authenticated;
select set_config('request.jwt.claim.sub','20261009-0000-4000-8000-000000000002',true);
select set_config('request.jwt.claim.role','authenticated',true);
select is((get_crm_insight_records_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}','visits',null,0,25)->>'total')::int,2,'visit detail reconciles');
select is((get_crm_insight_records_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}','purchases',null,0,25)->>'total')::int,1,'purchase detail distinct');
select throws_ok($$select get_crm_insights_v1('{"secret":"bad"}')$$,'22023',null,'unknown keys denied');
select throws_ok($$select get_crm_insight_records_v1('{}','revenue',null,0,25)$$,'22023',null,'unsupported metric denied');
select is((select (m->>'value')::numeric from jsonb_array_elements(get_crm_insights_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}')->'metrics')m where m->>'key'='purchase_rate'),50::numeric,'aggregate purchase rate has known outcomes denominator');
select is((select sum((m->>'count')::int) from jsonb_array_elements(get_crm_insights_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}')->'outcomes')m),2::bigint,'exact outcomes reconcile with visits');
select is((select (m->>'value')::numeric from jsonb_array_elements(get_crm_insights_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}')->'metrics')m where m->>'key'='unique_clients'),1::numeric,'repeat visits count one unique client');
select is((get_crm_insight_records_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}','unique_clients',null,0,25)->>'total')::int,1,'unique client detail reconciles');
select throws_ok($$select get_crm_insight_records_v1('{}','visits',null,0,null)$$,'22023',null,'null CRM limit rejected');
select is((get_crm_insight_records_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}','non_buying_reason','Synthetic price',0,25)->>'total')::int,1,'structured reason detail is distinct visits');
select is((select (m->>'value')::numeric from jsonb_array_elements(get_crm_insights_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000001"}')->'metrics')m where m->>'key'='completed_followup_updates'),1::numeric,'completed transitions count saved history once');
select throws_ok($$select get_crm_insights_v1('{"preset":"custom","from":"2026-10-09","to":null}')$$,'22023',null,'custom range requires both dates');
reset role;
insert into public.branches(id,name) values ('20261009-0000-4000-8000-000000000005','Synthetic other insights branch');
insert into client_timeline(client_id,event_date,event_type,buy_status,branch_id,salesperson_id) values ('20261009-0000-4000-8000-000000000003',now(),'NON_PURCHASE_VISIT','NO','20261009-0000-4000-8000-000000000005','20261009-0000-4000-8000-000000000002');
set local role authenticated;
select is((get_crm_insight_records_v1('{"preset":"today","branch_id":"20261009-0000-4000-8000-000000000005"}','visits',null,0,25)->>'total')::int,1,'active CRM staff retain company-wide branch reads');
reset role;
update public.users set active=false where id='20261009-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select get_crm_insights_v1('{}')$$,'42501',null,'inactive CRM user denied');
reset role;
update public.users set active=true where id='20261009-0000-4000-8000-000000000002';
update public.crm_sso_access_grants set active=false where crm_auth_user_id='20261009-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select get_crm_insight_records_v1('{}','visits',null,0,25)$$,'42501',null,'inactive CRM bridge denied');
select set_config('request.jwt.claim.sub','20261009-0000-4000-8000-000000000099',true);
select throws_ok($$select get_crm_insights_options_v1('{}')$$,'42501',null,'identity without CRM bridge denied');
select * from finish();
rollback;